import { useRef, useState } from 'react'

export function Login({ onLogin }: { onLogin: (v: Values) => Promise<Result> }) {
  const [errors, setErrors] = useState<Errors>({})
  const firstError = useRef<HTMLInputElement | null>(null)

  async function submit(values: Values) {
    const result = await onLogin(values)
    if (!result.ok) {
      setErrors(result.errors)
      queueMicrotask(() => firstError.current?.focus())
    }
  }

  return (
    <form onSubmit={handle(submit)}>
      <Field label="邮箱" name="email" error={errors.email} errorRef={errors.email ? firstError : undefined} />
      <Field label="密码" name="password" error={errors.password} errorRef={!errors.email && errors.password ? firstError : undefined} />
      {errors.form && <p role="alert">{errors.form}</p>}
      <button type="submit">登录</button>
    </form>
  )
}

